def length_of_longest_substring(s):
    last, start, best = {}, 0, 0
    for i, ch in enumerate(s):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = i
        best = max(best, i - start + 1)
    return best

def max_profit(prices):
    best, min_p = 0, float('inf')
    for p in prices:
        min_p = min(min_p, p)
        best = max(best, p - min_p)
    return best

